import React from "react";

const Feedback = () => {
  return (
    <div className="flex flex-col items-center justify-center min-h-[80vh] px-6 text-center">
      <h1 className="text-4xl font-bold mb-4 text-blue-100">AI Feedback Report</h1>
      <p className="text-blue-300 max-w-2xl mb-6">
        Here’s your personalized feedback based on your uploaded interview.  
        Analyze your tone, confidence, and communication skills.
      </p>
      <div className="bg-white/10 backdrop-blur-md p-6 rounded-lg w-full max-w-lg shadow-lg">
        <p>🎯 <strong>Tone:</strong> Positive and confident</p>
        <p>🗣️ <strong>Clarity:</strong> Excellent articulation</p>
        <p>💪 <strong>Body Language:</strong> Professional posture</p>
        <p>⭐ <strong>Overall Score:</strong> 9.2 / 10</p>
      </div>
    </div>
  );
};

export default Feedback;
